const p = Number(query.principal);
const annual = Number(query.annualRate);
const months = Math.round(Number(query.tenureMonths));
if (!(p > 0) || !(annual >= 0) || !(months > 0)) {
  return JSON.stringify({ error: 'Invalid input. principal must be > 0, annualRate >= 0, tenureMonths > 0.' });
}
const r = annual / 1200;
const emi = r === 0 ? p / months : (p * r * Math.pow(1 + r, months)) / (Math.pow(1 + r, months) - 1);
const total = emi * months;
const round = (x) => Math.round(x * 100) / 100;
return JSON.stringify({
  principal: round(p),
  annualRatePercent: annual,
  tenureMonths: months,
  monthlyEmi: round(emi),
  totalPayment: round(total),
  totalInterest: round(total - p),
  formula: 'EMI = P x r x (1+r)^n / ((1+r)^n - 1), r = annual rate / 1200, n = months'
});

